import{_ as s,l as o,o as e,c as l,v as r,p,x as t,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Treap","description":"","frontmatter":{"title":"Treap","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/treap.md","filePath":"cs/treap.md","lastUpdated":1789023840000}'),h={name:"cs/treap.md"};function T(m,a,A,_,B,E){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="treap" tabindex="-1">Treap <a class="header-anchor" href="#treap" aria-label="Permalink to &quot;Treap&quot;">​</a></h1><div class="epigraph"><p>键守 BST 序，堆序交给随机优先级；期望高度对数，旋转次数跟随机 BST 同分布。</p><footer>—— 据 Seidel and Aragon, Randomized Search Trees, Algorithmica 1996；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/sparse-set">上一课</a>收束了序列区间。有序字典主干已有<a href="/cs/bst">BST</a>、<a href="/cs/avl-rotate">AVL</a>、<a href="/cs/rbtree-intuition">红黑直觉</a>，着色与平衡因子都是确定修复。<a href="/cs/skip-list">跳表</a>用随机层高。本课不重画红黑 case。缺口是 Treap：随机堆优先级 + BST 键，期望 \\(O(\\log n)\\)，实现是旋转。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>确定平衡要写一长串旋转分类。随机 BST（按随机插入序）期望高度对数，但不能按任意插入序保证。Treap 给每个键独立均匀随机的优先级 \\(p(k)\\)，树同时满足：中序为键序，堆序为优先级（通常小根）。形状唯一：就是按 \\(p\\) 排序插入 BST 的结果。缺口是<strong>用随机优先级代替随机插入序</strong>，从而任意更新序列下期望仍对数。</p><p><span class="marginnote">Seidel–Aragon 称之为 randomized search tree。split/merge 实现与笛卡尔树插入同构，竞赛里常用无显式旋转的分裂合并。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入：按 BST 挂叶，再沿堆序上旋。删除：转到叶再摘，或先把优先级改成「无穷」再下旋。split(\\(T,k)\\)：按键切成 \\(\\lt k\\) 与 \\(\\ge k\\) 两棵 treap；merge 假定左树键全小于右树，按根优先级决定谁当根。期望 \\(O(\\log n)\\)。</p>',8)),(e(),p(c,null,{default:t(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E9%94%AE%3A%20BST%20%E5%BA%8F%22%5D%20--%3E%20NODE%5B%22%E8%8A%82%E7%82%B9%22%5D%0A%20%20PRI%5B%22%E9%9A%8F%E6%9C%BA%E4%BC%98%E5%85%88%E7%BA%A7%3A%20%E5%A0%86%E5%BA%8F%22%5D%20--%3E%20NODE%0A%20%20NODE%20--%3E%20ROT%5B%22%E4%B8%8A%E6%97%8B%20%2F%20%E4%B8%8B%E6%97%8B%E6%81%A2%E5%A4%8D%E5%A0%86%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与跳表：都是随机期望对数、保序。Treap 是树，中序递归；跳表是多层链表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>期望分析与随机 BST 相同：根是优先级最小的键，左右规模均匀于键秩。最坏仍可退化（优先级运气差），合同写期望，与跳表一致。不要用时间戳当优先级除非能证明随机性。</p><p>隐式 treap 用下标当键（子树 size），可当可分裂序列，本课点名：键变成位置，机制仍是 split/merge。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把并发 treap、或确定 treap（哈希优先级）的对抗分析写完。实时最坏路径用 AVL/红黑。下一课伸展树去掉随机与平衡位，改用摊还。</p><p>后课默认：随机平衡 BST 可以是 Treap。无额外随机、靠访问旋转的是 splay。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Treap：BST 键 + 随机堆优先级，期望对数。</li><li>split/merge 与旋转等价。</li><li>摊还、无随机的自调整是下一课。</li><li>出处：Seidel and Aragon, <em>Algorithmica</em>, 1996；Cormen et al.。</li></ul>',9))])}const u=s(h,[["render",T]]);export{f as __pageData,u as default};
